impl Specification {
    /// Register the two minted axes. MUST follow `add_eval_ir_stack_split`
    /// (which follows the minted stacking family: `ir_stkn_arm_*`,
    /// `ir_resolve_stack`, the `ir_mext_*` family the twin mirrors) and
    /// `add_eval_ir_steps` (`ir_steps_halted`).
    ///
    /// # Errors
    /// Returns `SpecError` if any declaration fails to elaborate or
    /// kernel-check -- by name, one declaration per arm.
    pub(super) fn add_eval_ir_stack_axes_minted(&mut self) -> Result<(), SpecError> {
        for (source, description) in DECLS {
            self.add_recursive_def(source, description)?;
        }
        Ok(())
    }
}

